package br.com.checkpoint.ocorrencias.web;
import br.com.checkpoint.ocorrencias.domain.*; import br.com.checkpoint.ocorrencias.dto.ApiDtos.*; import br.com.checkpoint.ocorrencias.repository.*;
import jakarta.validation.Valid; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.web.bind.annotation.*;
import java.util.*;
@RestController @RequestMapping("/api")
public class AdminController {
 private final UsuarioRepository users; private final AlunoRepository alunos; private final TurmaRepository turmas; private final MatriculaRepository matriculas; private final CategoriaRepository categorias; private final TipoOcorrenciaRepository tipos; private final PasswordEncoder encoder;
 public AdminController(UsuarioRepository u,AlunoRepository a,TurmaRepository t,MatriculaRepository m,CategoriaRepository c,TipoOcorrenciaRepository tp,PasswordEncoder e){users=u;alunos=a;turmas=t;matriculas=m;categorias=c;tipos=tp;encoder=e;}
 private void admin(){ }
 @PostMapping("/usuarios") @PreAuthorize("hasRole('ADMINISTRATIVO')") public UsuarioView criarUsuario(@Valid @RequestBody UsuarioRequest r){if(users.existsByLogin(r.login()))throw new IllegalArgumentException("Login já cadastrado");if(r.senha()==null||r.senha().length()<8)throw new IllegalArgumentException("Senha deve ter ao menos 8 caracteres");var u=users.save(new Usuario(r.nome(),r.login(),encoder.encode(r.senha()),r.perfil()));return uv(u);}
 @GetMapping("/usuarios") @PreAuthorize("hasRole('ADMINISTRATIVO')") public List<UsuarioView> usuarios(){return users.findAll().stream().map(this::uv).toList();}
 @PutMapping("/usuarios/{id}") @PreAuthorize("hasRole('ADMINISTRATIVO')") public UsuarioView atualizarUsuario(@PathVariable Long id,@Valid @RequestBody UsuarioRequest r){var u=users.findById(id).orElseThrow(()->new NoSuchElementException("Usuário não encontrado"));if(!u.getLogin().equals(r.login())&&users.existsByLogin(r.login()))throw new IllegalArgumentException("Login já cadastrado");u.atualizar(r.nome(),r.login(),r.perfil());if(r.senha()!=null&&!r.senha().isBlank()){if(r.senha().length()<8)throw new IllegalArgumentException("Senha deve ter ao menos 8 caracteres");u.setSenha(encoder.encode(r.senha()));}return uv(users.save(u));}
 @DeleteMapping("/usuarios/{id}") @PreAuthorize("hasRole('ADMINISTRATIVO')") public void inativarUsuario(@PathVariable Long id){var u=users.findById(id).orElseThrow(()->new NoSuchElementException("Usuário não encontrado"));u.setAtivo(false);users.save(u);}
 private UsuarioView uv(Usuario u){return new UsuarioView(u.getId(),u.getNome(),u.getLogin(),u.getPerfil(),u.isAtivo());}

 @PostMapping("/alunos") @PreAuthorize("hasRole('ADMINISTRATIVO')") public AlunoView criarAluno(@Valid @RequestBody AlunoRequest r){return av(alunos.save(new Aluno(r.nome(),r.dataNascimento(),r.fotoUrl())));}
 @GetMapping("/alunos") @PreAuthorize("hasAnyRole('ADMINISTRATIVO','PROFESSOR','ANALISTA_QUALIDADE','COORDENADOR')") public List<AlunoView> listarAlunos(){return alunos.findAll().stream().map(this::av).toList();}
 @GetMapping("/alunos/{id}") @PreAuthorize("hasAnyRole('ADMINISTRATIVO','PROFESSOR','ANALISTA_QUALIDADE','COORDENADOR')") public AlunoView aluno(@PathVariable Long id){return av(alunos.findById(id).orElseThrow(()->new NoSuchElementException("Aluno não encontrado")));}
 @PutMapping("/alunos/{id}") @PreAuthorize("hasRole('ADMINISTRATIVO')") public AlunoView atualizarAluno(@PathVariable Long id,@Valid @RequestBody AlunoRequest r){var a=alunos.findById(id).orElseThrow(()->new NoSuchElementException("Aluno não encontrado"));a.atualizar(r.nome(),r.dataNascimento(),r.fotoUrl());return av(alunos.save(a));}
 @DeleteMapping("/alunos/{id}") @PreAuthorize("hasRole('ADMINISTRATIVO')") public void inativarAluno(@PathVariable Long id){var a=alunos.findById(id).orElseThrow(()->new NoSuchElementException("Aluno não encontrado"));a.setAtivo(false);alunos.save(a);}
 private AlunoView av(Aluno a){return new AlunoView(a.getId(),a.getNome(),a.getDataNascimento(),a.getFotoUrl(),a.isAtivo());}

 @PostMapping("/turmas") @PreAuthorize("hasRole('ADMINISTRATIVO')") public TurmaView criarTurma(@Valid @RequestBody TurmaRequest r){return tv(turmas.save(new Turma(r.nome(),r.turno(),r.ano(),r.semestre())));}
 @GetMapping("/turmas") @PreAuthorize("hasAnyRole('ADMINISTRATIVO','PROFESSOR','ANALISTA_QUALIDADE','COORDENADOR')") public List<TurmaView> listarTurmas(){return turmas.findAll().stream().map(this::tv).toList();}
 @GetMapping("/turmas/{id}") @PreAuthorize("hasAnyRole('ADMINISTRATIVO','PROFESSOR','ANALISTA_QUALIDADE','COORDENADOR')") public TurmaView turma(@PathVariable Long id){return tv(turmas.findById(id).orElseThrow(()->new NoSuchElementException("Turma não encontrada")));}
 @PutMapping("/turmas/{id}") @PreAuthorize("hasRole('ADMINISTRATIVO')") public TurmaView atualizarTurma(@PathVariable Long id,@Valid @RequestBody TurmaRequest r){var t=turmas.findById(id).orElseThrow(()->new NoSuchElementException("Turma não encontrada"));t.atualizar(r.nome(),r.turno(),r.ano(),r.semestre());return tv(turmas.save(t));}
 @DeleteMapping("/turmas/{id}") @PreAuthorize("hasRole('ADMINISTRATIVO')") public void inativarTurma(@PathVariable Long id){var t=turmas.findById(id).orElseThrow(()->new NoSuchElementException("Turma não encontrada"));t.setAtiva(false);turmas.save(t);}
 private TurmaView tv(Turma t){return new TurmaView(t.getId(),t.getNome(),t.getTurno(),t.getAno(),t.getSemestre(),t.isAtiva());}

 @PostMapping("/matriculas") @PreAuthorize("hasRole('ADMINISTRATIVO')") public MatriculaView matricular(@Valid @RequestBody MatriculaRequest r){var a=alunos.findById(r.alunoId()).orElseThrow(()->new NoSuchElementException("Aluno não encontrado"));var t=turmas.findById(r.turmaId()).orElseThrow(()->new NoSuchElementException("Turma não encontrada"));if(!a.isAtivo()||!t.isAtiva())throw new IllegalArgumentException("Aluno e turma precisam estar ativos");if(matriculas.findByAlunoIdAndTurmaId(a.getId(),t.getId()).filter(Matricula::isAtiva).isPresent())throw new IllegalArgumentException("Aluno já matriculado nesta turma");var m=matriculas.save(new Matricula(a,t));return mv(m);}
 @GetMapping("/turmas/{id}/alunos") @PreAuthorize("hasAnyRole('ADMINISTRATIVO','PROFESSOR','ANALISTA_QUALIDADE','COORDENADOR')") public List<MatriculaView> alunosDaTurma(@PathVariable Long id){if(!turmas.existsById(id))throw new NoSuchElementException("Turma não encontrada");return matriculas.findByTurmaIdAndAtivaTrue(id).stream().map(this::mv).toList();}
 @GetMapping("/alunos/{id}/historico-turmas") @PreAuthorize("hasAnyRole('ADMINISTRATIVO','PROFESSOR','ANALISTA_QUALIDADE','COORDENADOR')") public List<MatriculaView> historicoTurmas(@PathVariable Long id){if(!alunos.existsById(id))throw new NoSuchElementException("Aluno não encontrado");return matriculas.findByAlunoId(id).stream().map(this::mv).toList();}
 @DeleteMapping("/matriculas/{id}") @PreAuthorize("hasRole('ADMINISTRATIVO')") public void encerrarMatricula(@PathVariable Long id){var m=matriculas.findById(id).orElseThrow(()->new NoSuchElementException("Matrícula não encontrada"));m.encerrar();matriculas.save(m);}
 private MatriculaView mv(Matricula m){return new MatriculaView(m.getId(),m.getAluno().getId(),m.getAluno().getNome(),m.getTurma().getId(),m.getTurma().getNome(),m.getDataMatricula(),m.isAtiva());}

 @PostMapping("/categorias") @PreAuthorize("hasRole('ADMINISTRATIVO')") public CategoriaView criarCategoria(@Valid @RequestBody CategoriaRequest r){return cv(categorias.save(new Categoria(r.nome(),r.descricao())));}
 @GetMapping("/categorias") @PreAuthorize("hasAnyRole('ADMINISTRATIVO','PROFESSOR','ANALISTA_QUALIDADE','COORDENADOR')") public List<CategoriaView> listarCategorias(){return categorias.findAll().stream().map(this::cv).toList();}
 @PutMapping("/categorias/{id}") @PreAuthorize("hasRole('ADMINISTRATIVO')") public CategoriaView atualizarCategoria(@PathVariable Long id,@Valid @RequestBody CategoriaRequest r){var c=categorias.findById(id).orElseThrow(()->new NoSuchElementException("Categoria não encontrada"));c.atualizar(r.nome(),r.descricao());return cv(categorias.save(c));}
 @DeleteMapping("/categorias/{id}") @PreAuthorize("hasRole('ADMINISTRATIVO')") public void inativarCategoria(@PathVariable Long id){var c=categorias.findById(id).orElseThrow(()->new NoSuchElementException("Categoria não encontrada"));c.setAtiva(false);categorias.save(c);}
 private CategoriaView cv(Categoria c){return new CategoriaView(c.getId(),c.getNome(),c.getDescricao(),c.isAtiva());}

 @PostMapping("/tipos-ocorrencia") @PreAuthorize("hasRole('ADMINISTRATIVO')") public TipoView criarTipo(@Valid @RequestBody TipoRequest r){var c=categorias.findById(r.categoriaId()).orElseThrow(()->new NoSuchElementException("Categoria não encontrada"));return tpv(tipos.save(new TipoOcorrencia(r.nome(),r.descricao(),c)));}
 @GetMapping("/tipos-ocorrencia") @PreAuthorize("hasAnyRole('ADMINISTRATIVO','PROFESSOR','ANALISTA_QUALIDADE','COORDENADOR')") public List<TipoView> listarTipos(){return tipos.findAll().stream().map(this::tpv).toList();}
 @GetMapping("/categorias/{id}/tipos") @PreAuthorize("hasAnyRole('ADMINISTRATIVO','PROFESSOR','ANALISTA_QUALIDADE','COORDENADOR')") public List<TipoView> tiposDaCategoria(@PathVariable Long id){return tipos.findByCategoriaIdAndAtivoTrue(id).stream().map(this::tpv).toList();}
 @PutMapping("/tipos-ocorrencia/{id}") @PreAuthorize("hasRole('ADMINISTRATIVO')") public TipoView atualizarTipo(@PathVariable Long id,@Valid @RequestBody TipoRequest r){var tp=tipos.findById(id).orElseThrow(()->new NoSuchElementException("Tipo não encontrado"));var c=categorias.findById(r.categoriaId()).orElseThrow(()->new NoSuchElementException("Categoria não encontrada"));tp.atualizar(r.nome(),r.descricao(),c);return tpv(tipos.save(tp));}
 @DeleteMapping("/tipos-ocorrencia/{id}") @PreAuthorize("hasRole('ADMINISTRATIVO')") public void inativarTipo(@PathVariable Long id){var tp=tipos.findById(id).orElseThrow(()->new NoSuchElementException("Tipo não encontrado"));tp.setAtivo(false);tipos.save(tp);}
 private TipoView tpv(TipoOcorrencia t){return new TipoView(t.getId(),t.getNome(),t.getDescricao(),t.getCategoria().getId(),t.getCategoria().getNome(),t.isAtivo());}
}
